from pypdf import PdfReader
reader=PdfReader('manuscript.pdf')
links=set()
for page in reader.pages:
    for ref in page.get('/Annots', []):
        annot=ref.get_object()
        action=annot.get('/A')
        if action and action.get('/URI'):
            links.add(str(action['/URI']))
for link in sorted(links):
    if any(word in link.lower() for word in ['github', 'gitlab', 'osf.', 'zenodo', 'huggingface', 'anonymous']):
        print(link)
print('Total external links:', len(links))
